import{_ as t,h as i,i as e,c as n,v as l,p as A,x as o,m as s,e as G,S as B}from"./chunks/framework.Dvtg8yj2.js";const T=JSON.parse('{"title":"GLM-4","description":"","frontmatter":{"title":"GLM-4","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/glm-4.md","filePath":"llm/glm-4.md","lastUpdated":1788454257000}'),h={name:"llm/glm-4.md"};function m(L,a,M,E,p,d){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="glm-4" tabindex="-1">GLM-4 <a class="header-anchor" href="#glm-4" aria-label="Permalink to &quot;GLM-4&quot;">​</a></h1><div class="epigraph"><p>把三代 ChatGLM 的预训练与对齐经验收进同一套解码器：去掉多余偏置，用分组查询压缓存，再用长上下文对齐把窗口拉到十万级。</p><footer>—— Team GLM, ChatGLM: A Family of Large Language Models from GLM-130B to GLM-4 All Tools, 2024</footer></div><p>GLM-4 是智谱与清华大学 GLM 团队在 2024 年交出的一代通用语言模型，报告覆盖 GLM-4、GLM-4-Air 与开源的 GLM-4-9B。它不再沿用 2021 年 GLM 论文里「自回归填空」作为对外叙事的主线，而是把解码器 Transformer 做成产品形态：十兆级中英为主的预训练、多阶段监督微调与人类反馈对齐，再加一条专门学「何时调工具」的 All Tools 路线。开源侧放出 GLM-4-9B（含 128K 与 1M 上下文的对话权重）以及 GLM-4V-9B。本篇只写这一代的架构取舍与对齐工序，不把 GLM-130B 的 DeepNorm 训练故事重写一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ChatGLM 从 6B 消费卡模型走到百亿、再走到与 GPT-4 同桌评测，中间换过目标函数、归一化、位置编码和注意力头布局。每一代都要同时满足三件事：中英双语质量、可服务的 KV 体积、以及从 2K 拉到 32K、128K 甚至 1M 时位置外推不崩。GLM-130B 用 DeepNorm 稳住百亿稠密训练；到 GLM-4，硬件与开源生态已经默认 <a href="/llm/rmsnorm">RMSNorm</a> 加 <a href="/llm/swiglu">SwiGLU</a>，再沿用 DeepNorm 只会让实现与社区核脱节。真正要重新决定的是：注意力还要不要每头一份 KV，偏置还要不要全局保留，长窗口是靠改位置编码还是靠专门的长文本对齐。</p><h3 id="从填空-glm-到产品解码器" tabindex="-1">从填空 GLM 到产品解码器 <a class="header-anchor" href="#从填空-glm-到产品解码器" aria-label="Permalink to &quot;从填空 GLM 到产品解码器&quot;">​</a></h3><p>早期 GLM 的二维位置来自「前缀 + 被掩码片段」的填空几何，和纯因果解码器的一维时间轴不是同一套。报告写明：GLM-4 把 <a href="/llm/rope">RoPE</a> 扩成二维形式，以兼容家族里仍存在的二维位置约定。对外服务的 GLM-4 语言系列按因果语言建模使用；读架构时不要把「二维 RoPE」理解成视觉网格，它首先是对 GLM 位置约定的延续，而不是另起一套多模态坐标。</p><p><span class="marginnote">报告里的 GLM-4、GLM-4-Air、GLM-4-9B 不是三套公式。差异主要在规模、延迟档位与是否开源权重。写「GLM-4 架构」应指报告列出的那组设计选择：除 QKV 外无偏置、RMSNorm、SwiGLU、二维 RoPE、GQA，以及用加宽 FFN 补回 GQA 砍掉的参数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预训练语料以中英网页、百科、书籍、代码与论文为主，夹少量其余语种，总量约十万亿 token。数据处理按去重、过滤、分词三段走：精确加模糊去重、去掉脏话与占位垃圾、用 byte-level BPE 把中文与多语言词表并进以 <code>cl100k_base</code> 为底的约 15 万词表，再对高质量来源升权。后训练是多阶段监督微调加上从人类反馈学习，提示来自真实交互而不是纯模板。GLM-4 All Tools 再对齐一层：模型要自己判断要不要打开浏览器、Python 解释器、文生图或用户函数。</p><h3 id="除-qkv-外去掉偏置" tabindex="-1">除 QKV 外去掉偏置 <a class="header-anchor" href="#除-qkv-外去掉偏置" aria-label="Permalink to &quot;除 QKV 外去掉偏置&quot;">​</a></h3><p>报告把「No Bias Except QKV」写成明确选项：除注意力的查询、键、值投影外，其余线性层去掉偏置。动机先是训练速度——少一批元素级加，也少一批要同步的参数。他们另外观察到长度外推略有改善。偏置在注意力分数里等价于对某些头加一个与内容无关的偏移；全部保留时，长序列上这些偏移会和位置编码纠缠。只把偏置留在 QKV，等于承认注意力打分仍需要一个可学习的零点，而不让 FFN 与输出投影再各自漂移。</p><h3 id="gqa-与加宽-ffn" tabindex="-1">GQA 与加宽 FFN <a class="header-anchor" href="#gqa-与加宽-ffn" aria-label="Permalink to &quot;GQA 与加宽 FFN&quot;">​</a></h3><p>推理 KV 是服务约束。GLM-4 用 <a href="/llm/gqa">分组查询注意力</a> 替换多头，组内共享键值，缓存按 KV 头数而不是查询头数增长。GQA 比 MHA 参数少，若总参数要大致对齐，缺的容量要补在别处。报告的补法是把 FFN 中间维设为隐藏维的 \\(10/3\\)，用稠密通道换回被砍掉的 KV 投影。这是参数预算的挪移，不是「GQA 天生更强」：质量若接近 MHA，靠的是组数仍够、以及 FFN 变宽后的表达力，而不是分组本身创造了新的注意力几何。</p>',14)),(e(),A(B,null,{default:o(()=>[G(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E7%BA%A6%2010T%20%E4%B8%AD%E8%8B%B1%E4%B8%BA%E4%B8%BB%E8%AF%AD%E6%96%99%22%5D%20--%3E%20PT%5B%22%E5%9B%A0%E6%9E%9C%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%0A%20%20PT%20--%3E%20ARCH%5B%22RMSNorm%20%2B%20SwiGLU%20%2B%20%E4%BA%8C%E7%BB%B4%20RoPE%20%2B%20GQA%22%5D%0A%20%20ARCH%20--%3E%20SFT%5B%22%E7%9C%9F%E5%AE%9E%E6%8F%90%E7%A4%BA%E4%B8%8A%E7%9A%84%E5%A4%9A%E9%98%B6%E6%AE%B5%20SFT%22%5D%0A%20%20SFT%20--%3E%20ALIGN%5B%22%E4%BA%BA%E7%B1%BB%E5%8F%8D%E9%A6%88%E5%AF%B9%E9%BD%90%22%5D%0A%20%20ALIGN%20--%3E%20CHAT%5B%22GLM-4%20%2F%20Air%20%2F%209B%20%E5%AF%B9%E8%AF%9D%22%5D%0A%20%20ALIGN%20--%3E%20TOOL%5B%22All%20Tools%EF%BC%9A%E8%87%AA%E4%B8%BB%E9%80%89%E5%B7%A5%E5%85%B7%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>把上述零件放进同一块，前向仍是标准 Pre-LN 解码器：RMSNorm 之后做 GQA，残差，再 RMSNorm 加 SwiGLU FFN。GQA 的缩放点积与因果掩码不变，变的是 \\(K,V\\) 的头数。二维 RoPE 作用在查询与键的旋转子空间上，不进入值。去掉非 QKV 偏置之后，FFN 是纯缩放，注意力分数仍可被 QKV 偏置平移。长上下文不是单靠 RoPE 基数魔法：报告把窗口从 ChatGLM 的 2K、ChatGLM2/3 的 32K，扩到 GLM-4 的 128K，并给开源 9B 一条 1M 的对话权重；长度能力同时依赖位置外推、长文本续训，以及 LongAlign 一类长上下文对齐，使模型在长提示上真的去读而不是只在短评测上好看。</p><h3 id="开源-9b-与闭源旗舰不是同一把尺子" tabindex="-1">开源 9B 与闭源旗舰不是同一把尺子 <a class="header-anchor" href="#开源-9b-与闭源旗舰不是同一把尺子" aria-label="Permalink to &quot;开源 9B 与闭源旗舰不是同一把尺子&quot;">​</a></h3><p>GLM-4-9B 用来验证这套架构在可下载权重上是否成立，也用来覆盖消费卡与单机部署。旗舰 GLM-4 与 Air 的评测数字（MMLU、IFEval、AlignBench、LongBench-Chat 等）描述的是更大、未全部开源的检查点。把 9B 的 HumanEval 去对 GPT-4 没有意义；反过来，也不能用旗舰榜把 9B 写成「开源 GPT-4」。All Tools 是对齐目标，不是架构模块：浏览器与解释器在模型外，模型学的是何时发工具调用、如何把结果接回对话。</p><p><span class="marginnote">GQA 省的是 decode 带宽与 KV 字节，不是 prefill 的 FLOPs 主导项。长上下文的瓶颈往往先是 KV，后是注意力核。GLM-4 把 FFN 加宽，训练算力上升，换的是推理期更小的 KV——这是服务场景下的不对称交易，短 prompt 离线打分未必划算。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>这套选择依赖已经成熟的开源核：RMSNorm、SwiGLU、RoPE、GQA 都有现成实现。二维 RoPE 与「只留 QKV 偏置」需要在移植时对齐报告，不能假定 Llama 形检查点直接加载。长窗口的 1M 权重更不能当成默认：位置编码、注意力实现、分页 KV 都要按百万级上下文准备，否则只是词表里写了 1M。</p><p>对齐质量高度依赖真实用户提示与中文评测。英文学术榜接近 GPT-4 并不自动等于中文产品体验；报告因此同时报 AlignBench 与双语 IFEval。工具调用若只在 SFT 里见过示范、没有 All Tools 那条专门对齐，模型会把「可以搜」说成「已经搜了」。安全与拒答也是后训练的一部分，不能从架构图读出来。</p><p>文献只引用官方技术报告（arXiv:2406.12793）以及文中点名的配套工作（LongAlign、ChatGLM-RLHF、AgentTuning 等）。不要把社区复现的层数表、第三方「等效 130B」传闻写进正文。开源权重以 THUDM / Zhipu 当时的模型卡与许可证为准。</p><p><span class="marginnote">ChatGLM-6B 能在消费卡 INT4 跑，靠的是 6B 稠密而不是 GLM-4 的 GQA。9B-Chat-1M 的显存账是「权重 + 百万上下文的 KV」，GQA 只缩小第二项。部署时先算 KV 字节再决定量化，不要只看参数量。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>GLM-4 语言系列包括旗舰、Air 与开源 9B，预训练约 10T、中英为主，后训练为多阶段 SFT 加人类反馈。</li><li>架构要点：除 QKV 外无偏置、RMSNorm、SwiGLU、二维 RoPE、GQA；FFN 中间维取隐藏维的 \\(10/3\\) 以补 GQA 少掉的参数。</li><li>长上下文靠位置方案、续训与长文本对齐共同撑起 128K，开源 9B 另提供 1M 对话权重。</li><li>All Tools 是对齐出来的工具使用策略，不是新的注意力公式。</li><li>开源 9B 与闭源旗舰共用设计语言，评测不可混用。</li><li>出处：Team GLM, <em>ChatGLM: A Family of Large Language Models from GLM-130B to GLM-4 All Tools</em>，arXiv:2406.12793，2024。</li></ul>',12))])}const F=t(h,[["render",m]]);export{T as __pageData,F as default};
